        openOn:            'hover',
        delay:             200,
        closeDelay:        150,
        animationIn:       'ts-navmenu-in',
        animationOut:      'ts-navmenu-out',
        animationDuration: 200,
        useViewport:       false,
        closeOnEscape:     true,
        closeOnOutside:    true,
